use super::*;

/// Repoint or drop every `composes` target that is not itself an impl in the resulting document.
///
/// `composes` models an edge in the ALGORITHM graph, so a target that is a registered platform module
/// or a component record is not an edge it can express — and writing one produces a dangling reference
/// the seed's own integrity guard rejects. Dropping THAT loses nothing real: the record still IMPORTS
/// the module and still resolves it through the registry; only the edge goes, and that edge never
/// existed.
///
/// A DECOMPOSED record is the other case, and dropping it there loses something that does exist.
/// `bsc graph extract` rewrites `X.rs` into `X--mod.rs` plus one child per leaf, so every edge
/// pointing at `X.rs` still has a target — the new parent — and the edge is as real as it ever was.
/// MEASURED on the first run of the extraction backlog: 19 records were repaired, and 17 of them
/// already carried BOTH forms so a drop was harmless, which is exactly why this went unnoticed. The
/// other two (`src-tauri--console--pty--launch--mod.rs` and `src-tauri--planner--workspace--mod.rs`)
/// carried only the flat id, and dropping it silently deleted a relationship the graph holds.
///
/// So: repoint to `<stem>--mod.rs` when that record exists, drop otherwise. Returns what it dropped
/// and what it repointed, per record, so the caller can report rather than silently prune.
pub fn prune_dangling_composes(store: &mut Value) -> Vec<(String, Vec<String>)> {
    let ids: std::collections::BTreeSet<String> = impls_of(store)
        .iter()
        .filter_map(|i| i.get("id").and_then(Value::as_str).map(str::to_string))
        .collect();
    let mut dropped = Vec::new();
    let Some(list) = store.get_mut("implementations").and_then(Value::as_array_mut) else {
        return dropped;
    };
    for rec in list.iter_mut() {
        let id = rec.get("id").and_then(Value::as_str).unwrap_or_default().to_string();
        let Some(c) = rec.get("composes").and_then(Value::as_array) else { continue };
        let (mut keep, gone): (Vec<Value>, Vec<Value>) = c
            .iter()
            .cloned()
            .partition(|t| t.as_str().is_some_and(|t| ids.contains(t)));
        if gone.is_empty() {
            continue;
        }
        let mut really_dropped: Vec<String> = Vec::new();
        for target in gone.iter().filter_map(|v| v.as_str()) {
            match target.strip_suffix(".rs").map(|stem| format!("{stem}--mod.rs")) {
                // The record was DECOMPOSED, not deleted: the edge has a target again.
                Some(successor) if ids.contains(&successor) => {
                    let already = keep.iter().any(|k| k.as_str() == Some(successor.as_str()));
                    if !already {
                        keep.push(Value::String(successor));
                    }
                }
                _ => really_dropped.push(target.to_string()),
            }
        }
        if !really_dropped.is_empty() {
            dropped.push((id, really_dropped));
        }
        if let Some(o) = rec.as_object_mut() {
            o.insert("composes".into(), Value::Array(keep));
        }
    }
    dropped
}
